<!doctype html>
<html>

<head>
    <meta charset="utf-8">
	  <meta http-equiv="Content-Type" content="text/html; charset=utf-8" />
    <title>Window Sticker</title>
	
    <style>
        @import url('http://fonts.googleapis.com/css2?family=Roboto:wght@100;300;400;500;700;900&display=swap');

        body {font-family: 'Roboto', sans-serif;}
        .f-left {float: left;}
        .f-right {float: right;}

        .t-right {
            text-align: right;
        }

        .t-center {
            text-align: center;
        }

        .t-left {
            text-align: left;
        }

        .logo-h {
            width: 150px;
        }

        .border {
            border: 1px solid #000;
            border-radius: 10px;
        }

.full-width {
padding: 50px 0px 0px;
width: 100%;
float: left;
}

        .report p strong {
            font-size: 17px;
        }

        .report p {
            color: #000;
            margin: 0px;
            padding-top: 8px;
            font-size: 13px;
        }

        .report p a {
            color: #000;
        }

        .head-block {
            overflow: hidden;
            margin-bottom: 15px;
        }

        .full-width h4 {
            margin: 0px;
            color: #000;
            font-size: 20px;
        }

        .border-bottom {
            border-bottom: 1px solid #0000006e;
            overflow: hidden;
            padding-top: 15px;
            margin-bottom: 15px;
        }

        .vehicle-information .information-d {
            padding-top: 5px;
        }

        .vehicle-information ul {
            margin-top: 0px;
            padding-left: 15px;
        }

        .vehicle-information ul li {
            width: 45%;
            float: left;
            color: #000;
            font-size: 16px;
            display: block;
            padding: 12px 0px;
            position: relative;
            padding-left: 25px;
        }

        img. {
            width: 25px;
            position: absolute;
            left: -2px;
            top: 10px;
        }

        .information-detail h3 {
            margin: 0px;
            color: #000;
            font-weight: 300;
            font-size: 22px;
        }

        .information-detail h5 {
            margin: 0px;
            color: #000;
            font-weight: 300;
            font-size: 35px;
        }

        .information-detail h1 {
            font-size: 40px;
            font-weight: bold;
            color: #000;
            margin: 0px;
        }

        .information-detail h1 sub {
            font-size: 20px;
            font-weight: 300;
        }

        .w-full {
            width: 100%;
        }

        .bottom-text {
            width: 100%;
            overflow: hidden;
            line-height: 15px;
        }

        .vehicle-information {
            overflow: hidden;
        }
		 .car-image {
            max-width: 100%;
            height: auto;
            display: block;
            margin-top: 10px;
            border-radius: 10px;
        }
		.left-block{width:70%;float:left;}
		.right-block{width:30%;float:right;}
		sticker {
            
            padding: 20px ;
            margin: 20px 10%;
            background-color: #f9f9f9;
        }

        .sticker-header {
            font-weight: bold;
            font-size: 18px;
        }

        .car-image {
            max-width: 100%;
            height: auto;
            display: block;
            margin-top: 10px;
            border-radius: 10px;
        }

        .car-info {
            display: flex;
            flex-direction: column;
            justify-content: space-between;
        }

        .info-text {
            font-size: 18px;
        }

        .qr-code {
            text-align: right;
        }

        .price-header {
            font-size: 36px;
            font-weight: bold;
            margin-bottom: 10px;
        }

        .details-row {
            font-size: 14px;
        }

     .icon-row {
    width: 100%;
    float: left;
    margin-bottom: 10px;
}

       

		.icon-circle img {
		width: 25px;
		height: 25px;
		float: left;
		border-radius: 50%;
		background-color: #dcdcdc;
		margin-right: 10px;
		padding: 18px;
		}

        .feature-text {
            font-size: 14px;
        }

        .section-header {
            font-size: 28px;
            font-weight: bold;
            text-align: left;
            margin-top: 30px;
        }

		.content-block {
		border: 1px solid #000;
		border-radius: 10px;
		padding: 25px;
		margin: 20px 0px;
		max-width:90%;
		}

.options-block {
border: 2px solid #000;
border-radius: 10px;
margin-top: 20px;
background-color: #ffffff;
padding: 0;
margin: 20px 0px;
max-width: 95%;
}

        .options-header {
            font-size: 20px;
            font-weight: bold;
            margin: 0; 
            background-color: #000; 
            color: #fff; 
            padding: 10px; 
            border-top-left-radius: 10px; 
            border-top-right-radius: 10px; 
        }

        .option-item {
            display: flex;
            align-items: center;
            margin-bottom: 10px;
        }

        .options-inner {
            padding: 10px 20px;
        }

.det-left{float:left; width:50%;}
.img-left{float:left; width:50%;}
.detail-rights{float:right;width:45%; padding:20px;}
.icon-row .icon-circle {width: 50%;float: left;margin:7px 0px;}
.footer-block {width: 100%;}
.footer-block .content-blocks {float: left;width: 45%;border: 2px solid #000;border-radius: 15px;margin-top: 20px;background-color: #ffffff;margin: 20px 0px;max-width: 95%;padding: 15px;}
.footer-block .options-block.content-blocks {padding: 0px;margin: 20px 10px;}
.content-left {width: 33%;float: left;margin-left: 20px;}
.content-left h2 {margin-bottom: 0px;font-size: 26px;margin-top: 10px;}
.content-left h4 {margin-bottom: 0px;margin-top: 10px;font-size: 20px;}
.image-left {width: 24%;float: left;}
.content-bottom .content-left {margin: 0px;}
.content-bottom h5 {margin-top: 10px;margin-bottom: 10px;}
.footer-block .content-block {
    width: 44% !important;
    float: left;
    margin: 0px 10px;
}

.footer-block .content-block .options-block {
    max-width: 100%;
    margin: 0px;
    border-bottom: 0px;
    border-left: 0px;
    border-right: 0px;
}
    </style>
</head>

<body style="width:1000px;margin:auto;">
    <div class="report" style="width: 100%;padding: 20px;margin: 20px auto;background-color: #f9f9f9;">
	<div class="top-bar">
     <div class="left-block">
                <div class="sticker-header">
                    <span style="font-size:14px; font-weight:600;">{{WEBSITE}} | {{BPHONE}}</span>
					<span style="font-size:18px; font-weight:400;display:block;"> {{BNAME}}</span>
                </div>
                <div class="info-text">
                    <p>{{BADDRESS}}, {{BCITY}}, {{BSTATE}} {{BCODE}}</p>
                </div>				
            </div>
			
			  <div class="right-block">
			<div class="qr-code">
                    {{QR}}
                </div>
				</div>
				</div>
				
				
				<div class="body-part" style="margin:-50px 0px 0px; float:left;width:100%;">
				<div class="img-left">
				<img src="{{IMAGE}}" class="car-image" style="width:100%; height:350px;">
               </div>
			   
			   <div class="detail-rights">
			   
			   <div class="price-header">${{PRICE}}</div>
			   
			   
			    <div class="details-row">
                    <div class="det-left">
                        <p><strong>Condition:</strong>  <span class="feature-text">Used </span></p>
                        <p><strong>Stock #:</strong>   <span class="feature-text"> {{STOCK}} </span></p>
                    </div>
                    <div class="det-left">
                        <p><strong>VIN:</strong> <span class="feature-text"> {{VIN}} </span></p>
                        <p><strong>Category:</strong> <span class="feature-text"> {{CERTIFICATION}} </span></p>
                    </div>
                </div>
				
				
				   <div class="vehicle-detail" style="padding:20px 0px; float:left;width:100%;">
                   <div class="icon-row">
                            <div class="icon-circle">
                       <img src="data:image/png;base64,
" class="icon-logo" />
							<span class="feature-text" style="font-size:20px;position: relative;top: 10px;"> {{ODOMETER}} {{KM_MILES}}</span>
                            </div>
							
							 <div class="icon-circle">
                       <img src="data:image/png;base64," class="icon-logo" />
							<span class="feature-text" style="font-size:20px;position: relative;top: 10px;"> {{DRIVETRAIN}} </span>
                            </div>
							
							
							 <div class="icon-circle">
                       <img src="data:image/png;base64," class="icon-logo" />
							<span class="feature-text" style="font-size:20px;position: relative;top: 10px;"> {{ENGINE}}</span>
                            </div>
							
							
							 <div class="icon-circle">
                       <img src="data:image/png;base64," class="icon-logo" />
							<span class="feature-text" style="font-size:20px;position: relative;top: 10px;"> {{TRANSMISSION}}</span>
                            </div>
							
							<div class="icon-circle">
                       <img src="data:image/png;base64,
" class="icon-logo" />
							<span class="feature-text" style="font-size:20px;position: relative;top: 10px;"> Ext: {{EXTERIOR_COLOR}} <br/> Int: {{INTERIOR_COLOR}}</span>
                            </div>
							
							 <div class="icon-circle">
                       <img src="data:image/png;base64," class="icon-logo" />
							<span class="feature-text" style="font-size:20px;position: relative;top: 10px;"> {{PASSENGERS}}</span>
                            </div>
							
							
							                            
                        </div>
						
						
						</div>
			   
				</div>
				</div>
				
				
				<div Class="vehicle-des" style="clear:both; width:100%">
				 <div class="section-header"> {{YEAR}} {{MAKE}} {{MODEL}} {{TRIM}}  </div>
				 
				  <!-- Content Block with Paragraphs -->
            <div class="content-block">
                <p> {{DESCRIPTION_LIMITED}}</p>
            </div>
			
				</div>
				
				
				
				<div class="options-block">
                <div class="options-header">Options</div>
                <div class="options-inner">
                   <p style="margin:0px;color: #000;font-size: 13px;font-weight: 300; line-height:27px;"> {{INSTALLED_OPTIONS}} </p>                 
                </div>
            </div>
			
			<div Class="footer-block">
			    <div class="content-block" style="min-height: 110px;">
                Price does not include taxes and licensing fees
            </div>
			<div class="content-block" style="padding: 0px;">
            <div class="options-block">
                <div class="options-header">Fuel Economy</div>
                <div class="options-inner">
                    <div class="">
                        <div class="image-left">
                            <img src="data:image/png;base64,
" alt="">
                        </div>
                        <div class="content-left">
                            <h2>{{FUEL_CITY}}/{{FUEL_HWY}}</h2>
                            City/hwy
                        </div>
                        <div class="content-left">
                            <h4>L/100 km</h4>
                            <div class="content-bottom">
                                <div class="content-left">
                                    <h5>{{FUEL_CITY}} </h5>
                                    City
                                </div>
                                <div class="content-left">
                                    <h5> {{FUEL_HWY}} </h5>
                                    Hwy
                                </div>
                            </div>
                        </div>
                    </div>
                    
                </div>
            </div>
			</div>			
			</div>
			
    </div>
</body>

</html>